const v = s.debate.agreement;s.gates = s.gates || {};
s.gates.logic = { score: +v.toFixed(2) * 1, pass: (v >= 0.6) };
s.gates.logic.note = 'audit premises, trace deduction';
return [{ json: s }];

const s = $input.first().json;
